Action: run_sql({'query': "SELECT \n    COUNT(DISTINCT e.gmap_id) as total_halal_establishments,\n    COUNT(DISTINCT CASE WHEN ea.attribute = 'Halal food' THEN e.gmap_id END) as count_by_attribute,\n    COUNT(DISTINCT CASE WHEN LOWER(e.name) LIKE '%halal%' THEN e.gmap_id END) as count_by_name,\n    COUNT(DISTINCT CASE WHEN LOWER(e.description) LIKE '%halal%' THEN e.gmap_id END) as count_by_desc,\n    COUNT(DISTINCT CASE WHEN LOWER(c.category) LIKE '%halal%' THEN e.gmap_id END) as count_by_category\nFROM establishments e\nLEFT JOIN establishment_attributes ea ON e.gmap_id = ea.gmap_id AND ea.attribute = 'Halal food'\nLEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nLEFT JOIN category c ON ec.category_id = c.category_id AND LOWER(c.category) LIKE '%halal%'\nWHERE ea.attribute = 'Halal food' \n   OR LOWER(e.name) LIKE '%halal%' \n   OR LOWER(e.description) LIKE '%halal%'\n   OR LOWER(c.category) LIKE '%halal%';\n"})

