Action: run_sql({'query': "WITH halal_gmap_ids AS (\n    SELECT DISTINCT gmap_id FROM establishment_attributes WHERE attribute = 'Halal food'\n    UNION\n    SELECT DISTINCT gmap_id FROM establishments WHERE LOWER(name) LIKE '%halal%' OR LOWER(description) LIKE '%halal%'\n    UNION\n    SELECT DISTINCT ec.gmap_id FROM establishment_categories ec JOIN category c ON ec.category_id = c.category_id WHERE LOWER(c.category) LIKE '%halal%'\n)\nSELECT \n    e.gmap_id,\n    e.name,\n    e.address,\n    e.avg_rating,\n    e.num_of_reviews,\n    e.price,\n    e.slchd_establishment_key\nFROM halal_gmap_ids h\nJOIN establishments e ON h.gmap_id = e.gmap_id;"})

