Action: run_sql({'query': "WITH halal_all AS (\n    SELECT DISTINCT e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price\n    FROM establishments e\n    LEFT JOIN establishment_attributes ea ON e.gmap_id = ea.gmap_id\n    LEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\n    LEFT JOIN category c ON ec.category_id = c.category_id\n    WHERE ea.attribute = 'Halal food' \n       OR LOWER(e.name) LIKE '%halal%' \n       OR LOWER(e.description) LIKE '%halal%'\n       OR LOWER(c.category) LIKE '%halal%'\n),\nslc_county_halal AS (\n    SELECT *,\n    CASE \n        WHEN address LIKE '%Salt Lake City%' THEN 'Salt Lake City'\n        WHEN address LIKE '%West Valley City%' THEN 'West Valley City'\n        WHEN address LIKE '%Sandy%' THEN 'Sandy'\n        WHEN address LIKE '%South Salt Lake%' THEN 'South Salt Lake'\n        WHEN address LIKE '%South Jordan%' THEN 'South Jordan'\n        WHEN address LIKE '%West Jordan%' THEN 'West Jordan'\n        WHEN address LIKE '%Midvale%' THEN 'Midvale'\n        WHEN address LIKE '%Holladay%' THEN 'Holladay'\n        WHEN address LIKE '%Cottonwood Heights%' THEN 'Cottonwood Heights'\n        WHEN address LIKE '%Millcreek%' THEN 'Millcreek'\n        WHEN address LIKE '%Draper%' THEN 'Draper'\n        WHEN address LIKE '%Murray%' THEN 'Murray'\n        WHEN address LIKE '%Taylorsville%' THEN 'Taylorsville'\n        WHEN address LIKE '%Riverton%' THEN 'Riverton'\n        WHEN address LIKE '%Herriman%' THEN 'Herriman'\n        WHEN address LIKE '%Kearns%' THEN 'Kearns'\n        WHEN address LIKE '%Magna%' THEN 'Magna'\n        ELSE 'Outside Salt Lake County / Other'\n    END AS city_group\n    FROM halal_all\n)\nSELECT city_group, COUNT(*) as count, ROUND(AVG(avg_rating), 2) as avg_rating, ROUND(AVG(num_of_reviews), 0) as avg_reviews\nFROM slc_county_halal\nGROUP BY city_group\nORDER BY count DESC;"})

